#### File: `src/components/NotificationsList.tsx`
```tsx
import React from 'react';

export interface Notification {
  id: string;
  message: string;
  timestamp: number; // Epoch timestamp in milliseconds
}

interface NotificationsListProps {
  notifications: Notification[];
  onClearAll: () => void;
}

export const NotificationsList: React.FC<NotificationsListProps> = ({
  notifications,
  onClearAll,
}) => {
  // Invert sorting order to descending (newest first) by timestamp
  const sortedNotifications = [...notifications].sort(
    (a, b) => b.timestamp - a.timestamp
  );

  return (
    <div className="notifications-container">
      <div className="notifications-header">
        <h2>Notifications</h2>
        <button 
          onClick={onClearAll} 
          data-testid="clear-all-btn"
          className="clear-btn"
        >
          Clear All
        </button>
      </div>
      {sortedNotifications.length === 0 ? (
        <p className="no-notifications">No notifications</p>
      ) : (
        <ul className="notifications-list">
          {sortedNotifications.map((notification) => (
            <li key={notification.id} className="notification-item">
              <span className="notification-message">{notification.message}</span>
              <span className="notification-time">
                {new Date(notification.timestamp).toLocaleTimeString()}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};
```

#### File: `src/components/__tests__/NotificationsList.test.tsx` (QA Verification)
```tsx
import React from 'react';
import { render, screen, fireEvent } from '@testing-library/react';
import '@testing-library/jest-dom';
import { NotificationsList, Notification } from '../NotificationsList';

const mockNotifications: Notification[] = [
  { id: '1', message: 'Oldest Notification', timestamp: 1000000000 },
  { id: '2', message: 'Newest Notification', timestamp: 3000000000 },
  { id: '3', message: 'Middle Notification', timestamp: 2000000000 },
];

describe('NotificationsList Component', () => {
  it('should sort notifications in descending order by timestamp', () => {
    render(<NotificationsList notifications={mockNotifications} onClearAll={jest.fn()} />);

    const items = screen.getAllByRole('listitem');

    // Verify descending order: Newest (3000000000) -> Middle (2000000000) -> Oldest (1000000000)
    expect(items[0]).toHaveTextContent('Newest Notification');
    expect(items[1]).toHaveTextContent('Middle Notification');
    expect(items[2]).toHaveTextContent('Oldest Notification');
  });

  it('should have data-testid="clear-all-btn" on the clear button and trigger onClearAll', () => {
    const handleClearAll = jest.fn();
    render(<NotificationsList notifications={mockNotifications} onClearAll={handleClearAll} />);

    const clearButton = screen.getByTestId('clear-all-btn');
    expect(clearButton).toBeInTheDocument();

    fireEvent.click(clearButton);
    expect(handleClearAll).toHaveBeenCalledTimes(1);
  });
});
```
